package com.stitchtrack.controller;
import com.stitchtrack.dao.*;import com.stitchtrack.model.User;import com.stitchtrack.util.ServletUtil;import jakarta.servlet.annotation.WebServlet;import jakarta.servlet.http.*;import java.io.IOException;import java.security.SecureRandom;
@WebServlet("/admin/action") public class AdminActionServlet extends HttpServlet{
 private final UserDAO users=new UserDAO();private final LaundryDAO laundry=new LaundryDAO();private final SupportDAO support=new SupportDAO();private final SecureRandom random=new SecureRandom();
 protected void doPost(HttpServletRequest r,HttpServletResponse s)throws IOException{User admin=ServletUtil.user(r);String a=r.getParameter("action");try{switch(a){case "verify"->users.setVerification(ServletUtil.longParam(r,"studentId"),Boolean.parseBoolean(r.getParameter("approve")));case "accept"->{long id=ServletUtil.longParam(r,"orderId");String token="STITCH-"+Long.toHexString(System.nanoTime()).toUpperCase()+Integer.toHexString(random.nextInt()).replace("-","").toUpperCase();laundry.accept(id,admin.getId(),r.getParameter("bag"),token);}case "stage"->laundry.updateStage(ServletUtil.longParam(r,"orderId"),r.getParameter("stage"));case "renewal"->support.resolveRenewal(ServletUtil.longParam(r,"requestId"),Boolean.parseBoolean(r.getParameter("approve")),r.getParameter("notes"));case "complaint"->support.resolveComplaint(ServletUtil.longParam(r,"complaintId"),r.getParameter("notes"));default->throw new IllegalArgumentException("Unknown action");}support.audit(admin.getId(),admin.getRole(),"Admin Action",a,r.getRemoteAddr());ServletUtil.flash(r,"success","Action completed successfully.");}catch(Exception e){ServletUtil.flash(r,"error",e.getMessage());}s.sendRedirect(r.getContextPath()+"/admin/dashboard");}
}
